-- V0.1 synthetic-only heartbeat foundation. A single latest operational state,
-- not a historical employee activity log. No devices, samples or accounts seeded.
-- Receipt timestamps are generated by PostgreSQL, not by endpoint clocks.
CREATE TABLE device_heartbeat_latest (
    device_id UUID PRIMARY KEY REFERENCES devices (id),
    received_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    agent_sent_at TIMESTAMPTZ NOT NULL,
    agent_version VARCHAR(64) NOT NULL,
    agent_status VARCHAR(16) NOT NULL
        CHECK (agent_status IN ('running', 'degraded', 'stopping')),
    policy_version BIGINT NOT NULL CHECK (policy_version > 0),
    capabilities_json JSONB NOT NULL
        CHECK (jsonb_typeof(capabilities_json) = 'object'),
    queue_count BIGINT NOT NULL CHECK (queue_count >= 0),
    queue_bytes BIGINT NOT NULL CHECK (queue_bytes >= 0),
    oldest_pending_at TIMESTAMPTZ,
    last_successful_upload_at TIMESTAMPTZ,
    dropped_count BIGINT NOT NULL CHECK (dropped_count >= 0),
    integrity_degraded BOOLEAN NOT NULL,
    collection_errors_json JSONB NOT NULL
        CHECK (jsonb_typeof(collection_errors_json) = 'array')
);
